    def test_summarize_rank_coverage_counts_classifies_cov_buckets(self):
        rank_map = nnf.build_rank_map((
            ("rank-1", ("A",)),
            ("rank-2", ("B",)),
            ("rank-3", ("C",)),
        ))
        stack_counts = {
            # singleton template stack is excluded
            ("A", "C"): 2,
            # stack X/A (fs_stack X + top A) projects to A (len=1)
            # => totally_unchecked
            ("A", "C/X"): 4,
            # stack A/B/C => cov=1
            ("C", "C/A/B"): 2,
            # stack A/X/C => 0<cov<1
            ("C", "C/A/X"): 3,
            # stack X/Y/Z => cov=0
            ("Z", "C/X/Y"): 5,
        }
        summary = nnf.summarize_rank_coverage_counts(stack_counts, rank_map)
        self.assertEqual(
            {
                "fully_checked": 2,
                "partially_checked": 3,
                "totally_unchecked": 9,
                "total": 14,
            },
            summary,
        )

