        rank_map = nnf.build_rank_map((("rank-1", ("A",)),))
        stack_counts = {
            ("A", "C"): 7,
        }
        summary = nnf.summarize_rank_coverage_counts(stack_counts, rank_map)
        self.assertEqual(
            {
                "fully_checked": 0,
                "partially_checked": 0,
                "totally_unchecked": 0,
                "total": 0,
            },
            summary,
        )

